#include <threads.h>

static mtx_t mtx;
static cnd_t cond;
static int ready = 0;

static int worker(void *arg) {
    (void)arg;
    mtx_lock(&mtx);
    ready = 1;
    cnd_signal(&cond);
    mtx_unlock(&mtx);
    return 0;
}

int main(void) {
    thrd_t thr;
    mtx_init(&mtx, mtx_plain);
    cnd_init(&cond);
    thrd_create(&thr, worker, NULL);
    mtx_lock(&mtx);
    while (!ready) {
        cnd_wait(&cond, &mtx);
    }
    mtx_unlock(&mtx);
    thrd_join(thr, NULL);
    cnd_destroy(&cond);
    mtx_destroy(&mtx);
    return 0;
}

